xpath.script:
{
    const info = odoo.__session_info__ || {};
    const pref = info.xet_theme;
    if (pref) {
        let mode = "";
        if (["dark", "light"].indexOf(mode) === -1) {
            const cookies = document.cookie.split(";").map(function (c) { return c.trim(); });
            mode = cookies.indexOf("color_scheme=dark") === -1 ? "light" : "dark";
        }
        let theme = "light";
        if (mode === "dark") {
            theme = ["dark_blue", "graphite"].indexOf(pref) === -1 ? "dark_blue" : pref;
        }
        const root = document.documentElement;
        root.dataset.xetMode = mode;
        root.dataset.xetThemePref = pref;
        root.dataset.xetTheme = theme;
    }
}
